function stopListening(){mic.classList.remove('listening');micTitle.textContent=t('micTitle')}
mic.addEventListener('click',()=>{
  if(!SpeechRecognition){micHint.textContent=t('voiceUnsupported');notify(t('voiceUnsupported'));return}
  if(mic.classList.contains('listening')){try{activeRecognition?.stop()}catch{}stopListening();return}
  const recognition=new SpeechRecognition();
  activeRecognition=recognition;
  recognition.lang={as:'as-IN',bn:'bn-IN',brx:'brx-IN',doi:'doi-IN',en:'en-IN',gu:'gu-IN',hi:'hi-IN',kn:'kn-IN',ks:'ks-IN',kok:'kok-IN',mai:'mai-IN',ml:'ml-IN',mni:'mni-IN',mr:'mr-IN',ne:'ne-IN',or:'or-IN',pa:'pa-IN',sa:'sa-IN',sat:'sat-IN',sd:'sd-IN',ta:'ta-IN',te:'te-IN',ur:'ur-IN'}[current]||'hi-IN';
  recognition.interimResults=false;recognition.maxAlternatives=1;
  recognition.onresult=event=>{const spoken=event.results?.[0]?.[0]?.transcript;if(!spoken){notify(t('noSpeech'));return}q.value=spoken;askDisha(spoken)};
  recognition.onerror=event=>{const message=(voiceErrors[current]||voiceErrors.en)[event.error]||t('noSpeech');micHint.textContent=message;notify(message);if(event.error==='network'||event.error==='language-not-supported')q.focus()};
  recognition.onend=()=>{activeRecognition=null;stopListening();if(q.value)micHint.textContent=t('micHint')};
  const startSafely=()=>{try{recognition.start()}catch(error){activeRecognition=null;stopListening();const key=error.name==='NotAllowedError'?'not-allowed':'no-speech';const message=(voiceErrors[current]||voiceErrors.en)[key]||t('noSpeech');micHint.textContent=message;notify(message)}};
  mic.classList.add('listening');micTitle.textContent=t('listening');micHint.textContent=t('micHint');
  if(typeof SpeechRecognition.available==='function'&&typeof SpeechRecognition.install==='function'&&'processLocally' in recognition){
    SpeechRecognition.available({langs:[recognition.lang],processLocally:true}).then(async status=>{
      if(status==='available'){recognition.processLocally=true;startSafely();return}
      if(status==='downloadable'||status==='downloading'){
        stopListening();micHint.textContent=(voiceStateCopy[current]||voiceStateCopy.en).downloading;
        const installed=await SpeechRecognition.install({langs:[recognition.lang],processLocally:true});
        const message=(voiceStateCopy[current]||voiceStateCopy.en)[installed?'installed':'downloadFailed'];micHint.textContent=message;notify(message);return;
      }
      recognition.processLocally=false;startSafely();
    }).catch(()=>{recognition.processLocally=false;startSafely()});
  }else startSafely();
});
